import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,readdirSync,existsSync} from 'node:fs';
import {decide,random} from '/home/holo/line/tools/measure/engine_decision.ts';
const root='/tmp/engine-topology-solver-20261104';
const cells=JSON.parse(readFileSync('/home/holo/line/tools/parity/cells.json','utf8')).cells;
function absoluteInterval(values:number[]) {
 const rng=random(0x2545f491),means:number[]=[];
 for(let i=0;i<50000;i++){
  let sum=0;for(let j=0;j<values.length;j++)sum+=values[Math.floor(rng()*values.length)];
  means.push(sum/values.length);
 }
 means.sort((a,b)=>a-b);
 return {mean:values.reduce((a,b)=>a+b,0)/values.length,interval95:[means[1250],means[48750]],resamples:50000,seed:'0x2545f491'};
}
const runs:any[]=[];
for(const name of readdirSync(root).sort()){
 const path=`${root}/${name}/result.json`;if(!existsSync(path))continue;
 const run=JSON.parse(readFileSync(path,'utf8'));
 if(run.schema!=='line.engine-ab.v1'||!run.complete)continue;
 assert.equal(run.samples.length,run.protocol.rounds*2);
 const pairs=Array.from({length:run.protocol.rounds},(_,round)=>{
  const a=run.samples.filter((s:any)=>s.round===round&&s.arm===0),b=run.samples.filter((s:any)=>s.round===round&&s.arm===1);
  assert.equal(a.length,1);assert.equal(b.length,1);assert.equal(a[0].frames,b[0].frames);
  if(run.protocol.mode==='compile')for(const sample of [a[0],b[0]])for(const m of sample.measurements){
   assert.equal(m.physicalFrames,cells[m.cell].physicalFrames);assert.equal(m.trackHash,cells[m.cell].trackHash);
  }
  return {base:a[0].nsPerFrame,candidate:b[0].nsPerFrame};
 });
 assert.deepEqual(decide(pairs,run.protocol.threshold),run.decision);
 const absolute=absoluteInterval(pairs.map(p=>p.candidate));
 runs.push({name,stage:run.protocol.stage,mode:run.protocol.mode,absolute,paired:run.decision,
  targetSatisfied:run.protocol.mode==='compile'&&run.protocol.stage==='confirm'&&run.protocol.cells.join(',')==='61'&&run.performanceQualified&&absolute.interval95[1]<7000});
}
writeFileSync(`${root}/audit.json`,JSON.stringify({status:'PASS: paired decisions and exact compile work/output reproduced from raw samples',absoluteMethod:'Fixed-sample nonparametric percentile bootstrap of candidate means, 50,000 resamples; only fresh confirmed cell61 runs can satisfy target.',runs},null,2)+'\n');
console.log(runs.map(r=>({name:r.name,mean:r.absolute.mean,interval95:r.absolute.interval95,target:r.targetSatisfied})));

